session_start();include 'conn.php';include 'auth.php';require_roles(['buyer']);$uid=(int)$_SESSION['user_id'];$request_id=(int)($_GET['request_id']??0);
$r=mysqli_query($con,"SELECT fr.request_id,fr.quantity,t.tree_id,t.species,t.unit_price,p.plantation_id,p.plantation_name,p.owner_id,u.full_name owner_name FROM forest_requests fr JOIN trees t ON t.tree_id=fr.tree_id JOIN plantations p ON p.plantation_id=t.plantation_id JOIN users u ON u.user_id=p.owner_id LEFT JOIN payments pay ON pay.request_id=fr.request_id WHERE fr.request_id=$request_id AND fr.requester_id=$uid AND fr.request_type='buy_trees' AND fr.status='approved' AND fr.fulfillment_status='awaiting_payment' AND pay.payment_id IS NULL");$x=$r?mysqli_fetch_assoc($r):null;if(!$x){flash('danger','Payment is only available for an approved, unpaid buying request.');redirect('requests.php');}$total=(int)$x['quantity']*(float)$x['unit_price'];
$page_title='Pay approved purchase';include 'includes/header.php';include 'includes/navbar.php';?>
<h1 class="page-title h2 mb-3">Pay approved purchase</h1><div class="card border-0 shadow-sm"><div class="card-body p-4"><form method="post" action="payment_save.php"><input type="hidden" name="request_id" value="<?= (int)$x['request_id'] ?>"><div class="row g-3"><div class="col-md-6"><label class="form-label">Owner</label><input class="form-control" value="<?= e($x['owner_name']) ?>" disabled></div><div class="col-md-6"><label class="form-label">Plantation</label><input class="form-control" value="<?= e($x['plantation_name']) ?>" disabled></div><div class="col-md-6"><label class="form-label">Approved trees</label><input class="form-control" value="<?= e(number_format($x['quantity']).' × '.$x['species']) ?>" disabled></div><div class="col-md-6"><label class="form-label">NAEB price</label><input class="form-control" value="<?= e(money($x['unit_price'])) ?> each" disabled></div><div class="col-md-6"><label class="form-label">Payment method</label><select class="form-select" name="payment_method" required><option>Bank transfer</option><option>Mobile money</option><option>Cash</option></select></div></div><div class="alert alert-light border mt-3">Total: <strong><?= e(money($total)) ?></strong>. Quantity and price are locked to the forestry-approved request.</div><button class="btn btn-success" name="save">Submit payment to owner</button> <a class="btn btn-light" href="requests.php">Cancel</a></form></div></div><?php include 'includes/footer.php';?>
